<script setup lang="ts">import{useForm,usePage}from'@inertiajs/vue3';import MainLayout from'../../Layouts/MainLayout.vue';const p=defineProps<{students:any[];items:{data:any[]}}>(),page=usePage();const f=useForm({siswa_id:'',tanggal:new Date().toISOString().slice(0,10),jenis:'masuk',jumlah:'',keterangan:''});const save=()=>f.post('/transaksi',{onSuccess:()=>f.reset('jumlah','keterangan')});const rp=(v:any)=>Number(v??0).toLocaleString('id-ID');</script>
<template><MainLayout><main class="p-4 sm:p-6 lg:p-8"><div class="mx-auto max-w-7xl"><div v-if="page.props.flash?.success" class="mb-4 rounded-lg bg-emerald-50 p-3 text-sm text-emerald-700">{{page.props.flash.success}}</div><div class="mb-6"><p class="text-sm font-bold uppercase tracking-widest text-indigo-600">Operasional</p><h1 class="mt-2 text-2xl font-bold">Transaksi</h1><p class="text-sm text-slate-500">Catat setoran dan penarikan langsung pada halaman transaksi.</p></div><section class="sneat-card p-5"><h2 class="font-bold">Transaksi baru</h2><form @submit.prevent="save" class="mt-4 grid gap-3 md:grid-cols-5"><select v-model="f.siswa_id" required><option value="">Pilih siswa</option><option v-for="s in p.students" :value="s.id">{{s.nis}} · {{s.nama}}</option></select><input v-model="f.tanggal" type="date" required><select v-model="f.jenis"><option value="masuk">Setoran</option><option value="keluar">Penarikan</option></select><input v-model="f.jumlah" type="number" min="1" placeholder="Jumlah" required><button class="sneat-primary rounded px-4 py-2 text-sm font-semibold text-white">Simpan</button><input v-model="f.keterangan" placeholder="Keterangan" class="md:col-span-5"></form></section><section class="sneat-card mt-6 overflow-hidden"><div class="border-b p-5"><b>Riwayat transaksi</b></div><div class="overflow-x-auto"><table class="sneat-table w-full text-left text-sm"><thead class="text-xs uppercase"><tr><th class="p-4">Tanggal</th><th class="p-4">Siswa</th><th class="p-4">Jenis</th><th class="p-4 text-right">Jumlah</th><th class="p-4 text-right">Saldo</th><th class="p-4">Keterangan</th></tr></thead><tbody class="divide-y"><tr v-for="x in p.items.data" :key="x.id"><td class="p-4">{{x.tanggal}}</td><td class="p-4 font-semibold">{{x.siswa}}</td><td class="p-4">{{x.jenis==='masuk'?'Setoran':'Penarikan'}}</td><td class="p-4 text-right">Rp {{rp(x.jumlah)}}</td><td class="p-4 text-right">Rp {{rp(x.saldo)}}</td><td class="p-4 text-slate-500">{{x.keterangan||'—'}}</td></tr><tr v-if="!p.items.data.length"><td colspan="6" class="p-10 text-center text-slate-400">Belum ada transaksi.</td></tr></tbody></table></div></section></div></main></MainLayout></template>
